/* ===== render.js ===== */
/* ==========================================================================
   Digi2U 2026 — grid renderers
   Each renderer maps to an Elementor widget loop:
     cards()  → Image Box grid  · tiles() → Icon Box grid · tiers() → Price Table
   ========================================================================== */
(function () {
  'use strict';

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function el(id) { return document.getElementById(id); }

  /* Image-Box style cards driven by a keyed object. */
  function cards(targetId, dict, type, opts) {
    var host = el(targetId);
    if (!host) return;
    opts = opts || {};
    var keys = opts.only || Object.keys(dict);
    host.innerHTML = keys.map(function (k) {
      var d = dict[k];
      if (!d) return '';
      return '<button class="card reveal" type="button" data-lb="' + type + ':' + esc(k) + '">' +
        '<div class="card-media">' +
          (d.tag ? '<span class="card-tag">' + esc(d.tag) + '</span>' : '') +
          (d.img ? '<img src="' + esc(d.img) + '" alt="' + esc(d.title || d.name) + '" loading="lazy">' : '') +
        '</div>' +
        '<div class="card-body">' +
          (d.kicker ? '<div class="card-kicker">' + esc(d.kicker) + '</div>' : '') +
          '<h3 class="h-card">' + esc(d.title || d.name) + '</h3>' +
          '<p class="card-desc">' + esc(d.short || d.desc) + '</p>' +
          '<span class="card-more">' + esc(opts.cta || 'Learn More') + '</span>' +
        '</div>' +
      '</button>';
    }).join('');
  }

  /* Team cards from an array. */
  function people(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (p) {
      /* The 2026 team cards carry the name and role baked into the artwork, so
         the visible text block is suppressed to avoid showing each name twice.
         Name and role still travel in alt text — screen readers and search
         engines need them, and the card image alone gives them nothing. */
      var labelled = /d2u-team-/.test(p.img || '');
      return '<button class="card card-person' + (labelled ? ' card-person-art' : '') +
        ' reveal" type="button" data-lb="person:' + esc(p.id) + '"' +
        ' aria-label="' + esc(p.name) + ' — ' + esc(p.role) + '. Read bio">' +
        '<div class="card-media">' +
          (p.img ? '<img src="' + esc(p.img) + '" alt="' + esc(p.name) + ' — ' + esc(p.role) + '" loading="lazy">' : '') +
        '</div>' +
        (labelled ? '' :
        '<div class="card-body">' +
          '<div class="card-kicker">' + esc(p.role) + '</div>' +
          '<h3 class="h-card">' + esc(p.name) + '</h3>' +
          '<span class="card-more">Read Bio</span>' +
        '</div>') +
      '</button>';
    }).join('');
  }

  /* Icon-Box style tiles driven by a keyed object. */
  function tiles(targetId, dict, type, opts) {
    var host = el(targetId);
    if (!host) return;
    opts = opts || {};
    host.innerHTML = Object.keys(dict).map(function (k) {
      var d = dict[k];
      return '<button class="tile reveal" type="button" data-lb="' + type + ':' + esc(k) + '">' +
        '<div class="tile-icon">' + esc(d.icon || (d.title || d.name || '').slice(0, 2).toUpperCase()) + '</div>' +
        (d.tag ? '<div class="card-kicker">' + esc(d.tag) + '</div>' : '') +
        (d.status ? '<div class="card-kicker">' + esc(d.status) + '</div>' : '') +
        '<h3 class="h-card">' + esc(d.title || d.name) + '</h3>' +
        '<p class="tile-desc">' + esc(d.short || d.desc) + '</p>' +
        '<span class="card-more">' + esc(opts.cta || 'More Info') + '</span>' +
      '</button>';
    }).join('');
  }

  /* Events from an array. */
  function events(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (d, i) {
      return '<button class="tile reveal" type="button" data-lb="event:' + i + '">' +
        '<div class="tile-icon">' + String(i + 1).padStart(2, '0') + '</div>' +
        '<div class="card-kicker">' + esc(d.tag) + '</div>' +
        '<h3 class="h-card">' + esc(d.title) + '</h3>' +
        '<p class="tile-desc">' + esc(d.desc) + '</p>' +
        '<span class="card-more">Event Details</span>' +
      '</button>';
    }).join('');
  }

  /* Sponsorship tiers — Elementor Price Table. */
  function tiers(targetId, dict) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = Object.keys(dict).map(function (k) {
      var d = dict[k];
      return '<div class="tier reveal' + (d.featured ? ' featured' : '') + '">' +
        '<div class="tier-tag">' + esc(d.tag) + '</div>' +
        '<h3 class="h-card">' + esc(d.name) + '</h3>' +
        '<div class="tier-amt">' + esc(d.amount) + '</div>' +
        '<ul>' + d.benefits.map(function (b) { return '<li>' + esc(b) + '</li>'; }).join('') + '</ul>' +
        '<button class="btn btn-' + (d.featured ? 'primary' : 'ghost') + '" type="button" data-lb="tier:' + esc(k) + '">Full Details</button>' +
      '</div>';
    }).join('');
  }

  /* Static stat bar — Elementor Counter. */
  function stats(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (s) {
      return '<div class="stat reveal"><div class="stat-n">' + esc(s.n) + '</div><div class="stat-l">' + esc(s.label) + '</div></div>';
    }).join('');
  }

  /* Numbered blocks — pillars, values. */
  function numbered(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (v) {
      return '<div class="reveal"><div class="n">' + esc(v.n) + '</div><h3>' + esc(v.title) + '</h3><p>' + esc(v.desc) + '</p></div>';
    }).join('');
  }

  /* Theory of change spine. */
  function theory(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (t, i) {
      return '<div class="theory-step reveal" style="--fill:' + Math.round(((i + 1) / arr.length) * 100) + '%">' +
        '<div class="theory-n">' + esc(t.step) + '</div>' +
        '<h3>' + esc(t.title) + '</h3>' +
        '<p>' + esc(t.desc) + '</p>' +
      '</div>';
    }).join('');
  }

  /* Marquee strip. */
  function marquee(targetId, items) {
    var host = el(targetId);
    if (!host) return;
    var row = items.map(function (i) { return '<span class="marquee-item">' + esc(i) + '</span>'; }).join('');
    host.innerHTML = row + row;
  }

  /* Activity gallery. opts.limit caps the tile count; opts.feature makes the
     first tile 2×2; opts.filters renders category chips. */
  function gallery(targetId, items, opts) {
    var host = el(targetId);
    if (!host) return;
    opts = opts || {};

    function tiles(list) {
      return list.map(function (p) {
        var i = items.indexOf(p);
        return '<button class="gal-item' + (opts.feature && p === list[0] ? ' wide' : '') + '" type="button" data-lb="photo:' + i + '">' +
          '<img src="' + esc(p.src) + '" alt="' + esc(p.cap) + '" loading="lazy">' +
          '<span class="gal-cap"><span class="gal-cat">' + esc(p.cat) + '</span>' + esc(p.cap) + '</span>' +
        '</button>';
      }).join('');
    }

    var shown = opts.limit ? items.slice(0, opts.limit) : items;
    host.innerHTML = tiles(shown);

    if (!opts.filters) return;
    var bar = el(opts.filters);
    if (!bar) return;
    var cats = ['All'];
    items.forEach(function (p) { if (cats.indexOf(p.cat) < 0) cats.push(p.cat); });
    bar.innerHTML = cats.map(function (c, i) {
      return '<button class="gal-filter" type="button" aria-pressed="' + (i === 0) + '" data-cat="' + esc(c) + '">' + esc(c) + '</button>';
    }).join('');
    bar.addEventListener('click', function (e) {
      var b = e.target.closest('.gal-filter');
      if (!b) return;
      bar.querySelectorAll('.gal-filter').forEach(function (x) { x.setAttribute('aria-pressed', String(x === b)); });
      var c = b.getAttribute('data-cat');
      var list = c === 'All' ? items : items.filter(function (p) { return p.cat === c; });
      host.innerHTML = tiles(opts.limit ? list.slice(0, opts.limit) : list);
    });
  }

  /* Day-in-the-life strip. */
  function moments(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (m) {
      return '<div class="moment reveal">' +
        '<div class="moment-img"><img src="' + esc(m.img) + '" alt="' + esc(m.title) + '" loading="lazy"></div>' +
        '<div class="moment-body">' +
          '<div class="moment-when">' + esc(m.when) + '</div>' +
          '<h3>' + esc(m.title) + '</h3>' +
          '<p>' + esc(m.desc) + '</p>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  /* Partner / sponsor logo wall. */
  function logos(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (l) {
      return '<div class="logo-cell reveal"><img src="' + esc(l.src) + '" alt="' + esc(l.name) + '" loading="lazy"></div>';
    }).join('');
  }

  /* Charter block. */
  function charter(targetId, c) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML =
      '<div class="charter reveal">' +
        '<p class="charter-lead">' + esc(c.lead) + '</p>' +
        '<p class="charter-body">' + esc(c.body) + '</p>' +
      '</div>';
  }

  /* ---- Phase 2 ---- */

  function stagger(i) { return ' data-d="' + ((i % 7) + 1) + '"'; }

  /* THE NEED — national workforce data. Every cell carries its source. */
  function need(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (s, i) {
      var src = s.href
        ? '<a href="' + esc(s.href) + '" target="_blank" rel="noopener">' + esc(s.source) + '</a>'
        : esc(s.source);
      return '<div class="need-cell reveal"' + stagger(i) + '>' +
        '<div class="need-n">' + esc(s.n) + '</div>' +
        '<div class="need-label">' + esc(s.label) + '</div>' +
        '<div class="need-src">Source: ' + src + '</div>' +
      '</div>';
    }).join('');
  }

  /* OUR IMPACT — Digi2U figures only. Pending cards render visibly empty. */
  function metrics(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (m, i) {
      if (m.pending) {
        return '<div class="metric pending reveal"' + stagger(i) + '>' +
          '<div class="metric-n">—</div>' +
          '<div class="metric-l">' + esc(m.label) + '</div>' +
          '<div class="metric-tag">Tracking</div>' +
        '</div>';
      }
      return '<div class="metric reveal"' + stagger(i) + '>' +
        '<div class="metric-n">' + esc(m.n) + '</div>' +
        '<div class="metric-l">' + esc(m.label) + '</div>' +
        (m.note ? '<div class="metric-note">' + esc(m.note) + '</div>' : '') +
      '</div>';
    }).join('');
  }

  /* Program categories. Each child program opens its existing popup. */
  function categories(targetId, cats, lookup) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = cats.map(function (c, i) {
      var items = c.programs.map(function (k) {
        var p = lookup[k];
        if (!p) return '';
        var isCert = /certification/i.test(p.tag || '');
        return '<li><button type="button" data-lb="program:' + esc(k) + '">' +
          esc(p.title) +
          (isCert ? '<span class="badge">Cert</span>' : '') +
        '</button></li>';
      }).join('');
      return '<div class="cat reveal"' + stagger(i) + '>' +
        '<div class="cat-media">' +
          '<span class="cat-count">' + c.programs.length + ' Tracks</span>' +
          (c.img ? '<img src="' + esc(c.img) + '" alt="' + esc(c.title) + '" loading="lazy">' : '') +
        '</div>' +
        '<div class="cat-body">' +
          '<div class="cat-kicker">' + esc(c.kicker) + '</div>' +
          '<h3>' + esc(c.title) + '</h3>' +
          '<p class="cat-desc">' + esc(c.desc) + '</p>' +
          '<ul class="cat-list">' + items + '</ul>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  /* Donation impact cards. */
  function giving(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (g, i) {
      return '<div class="give reveal"' + stagger(i) + '>' +
        '<div class="give-icon">' + esc(g.icon) + '</div>' +
        '<h3>' + esc(g.title) + '</h3>' +
        '<p>' + esc(g.desc) + '</p>' +
        (g.amount ? '<div class="give-amt">' + esc(g.amount) + '</div>' : '') +
      '</div>';
    }).join('');
  }

  /* Testimonials. Renders real entries only — no placeholder cards.
     With D2U_STORIES empty the whole section is removed from the page, so
     nothing advertises that testimony is missing. Add entries and the section
     reappears automatically. */
  function stories(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    if (!arr || !arr.length) {
      var sec = host.closest('section');
      if (sec) sec.remove(); else host.remove();
      return;
    }
    host.innerHTML = arr.map(function (s, i) {
      return '<div class="story reveal"' + stagger(i) + '>' +
        '<p class="story-quote">' + esc(s.quote) + '</p>' +
        '<div class="story-who">' +
          '<img class="story-img" src="' + esc(s.img) + '" alt="' + esc(s.name) + '" loading="lazy">' +
          '<div><div class="story-name">' + esc(s.name) + '</div>' +
          '<div class="story-prog">' + esc(s.program) + '</div></div>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  /* Our Story pillars. */
  function pillars(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (p, i) {
      return '<div class="story-pillar reveal"' + stagger(i) + '>' +
        '<div class="tile-icon">' + esc(p.icon) + '</div>' +
        '<h3>' + esc(p.title) + '</h3>' +
        '<p>' + esc(p.desc) + '</p>' +
      '</div>';
    }).join('');
  }

  /* Physical locations, with the grant-eligibility evidence attached. */
  function sites(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (s, i) {
      var stats = (s.stats || []).map(function (m) {
        return '<div><strong>' + esc(m[0]) + '</strong><span>' + esc(m[1]) + '</span></div>';
      }).join('');
      return '<div class="loc reveal"' + stagger(i) + '>' +
        '<div class="loc-role">' + esc(s.role) + '</div>' +
        '<h3>' + esc(s.name) + '</h3>' +
        '<div class="loc-place">' + esc(s.place) + '</div>' +
        '<p>' + esc(s.body) + '</p>' +
        (stats ? '<div class="loc-stats">' + stats + '</div>' : '') +
      '</div>';
    }).join('');
  }

  /* Founder card. */
  function founder(targetId, f) {
    var host = el(targetId);
    if (!host || !f) return;
    host.innerHTML =
      '<div class="founder reveal">' +
        '<img class="founder-img" src="' + esc(f.img) + '" alt="' + esc(f.name) + '" loading="lazy">' +
        '<div class="founder-body">' +
          '<p class="founder-quote">“' + esc(f.quote) + '”</p>' +
          '<p class="founder-story">' + esc(f.story) + '</p>' +
          '<div class="founder-who"><strong>' + esc(f.name) + '</strong><span>' + esc(f.role) + '</span></div>' +
        '</div>' +
      '</div>';
  }

  /* Funder eligibility panel. */
  function funder(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (r, i) {
      return '<div class="fund-row reveal"' + stagger(i) + '>' +
        '<div class="fund-k">' + esc(r.k) + '</div>' +
        '<div class="fund-v">' + esc(r.v) + '</div>' +
        '<div class="fund-note">' + esc(r.note) + '</div>' +
      '</div>';
    }).join('');
  }

  /* ---------- Donate page ---------- */

  /* An external destination gets the security attributes; an in-page jump must
     not, because rel/target on a "#stock" link is meaningless noise. */
  function linkAttrs(d) {
    return ' href="' + esc(d.href) + '"' +
      (d.external ? ' target="_blank" rel="noopener"' : '');
  }

  /* The three ways to give. Each card is a real link, not a lightbox trigger —
     the whole point of the page is that the button completes a donation. */
  function ways(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (w, i) {
      return '<div class="way reveal"' + stagger(i) + '>' +
        '<div class="tile-icon">' + esc(w.icon) + '</div>' +
        '<div class="card-kicker">' + esc(w.tag) + '</div>' +
        '<h3 class="h-card">' + esc(w.title) + '</h3>' +
        '<p class="tile-desc">' + esc(w.desc) + '</p>' +
        '<a class="btn btn-primary way-cta"' + linkAttrs(w) + '>' + esc(w.cta) + '</a>' +
      '</div>';
    }).join('');
  }

  /* Campaign cards with the progress bar the previous site carried. The bar is
     decorative, so the accessible name lives on the wrapper and the fill is
     driven by a custom property rather than an inline width. */
  function causes(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (c, i) {
      var pct = Math.max(0, Math.min(100, Number(c.pct) || 0));
      return '<div class="cause reveal"' + stagger(i) + '>' +
        '<div class="cause-media"><img src="' + esc(c.img) + '" alt="' + esc(c.title) + '" loading="lazy"></div>' +
        '<div class="cause-body">' +
          '<div class="card-kicker">' + esc(c.kicker) + '</div>' +
          '<h3 class="h-card">' + esc(c.title) + '</h3>' +
          '<p class="cause-head">' + esc(c.head) + '</p>' +
          '<p class="cause-desc">' + esc(c.desc) + '</p>' +
          '<div class="cause-nums"><span>Raised ' + esc(c.raised) + '</span><span>Goal ' + esc(c.goal) + '</span></div>' +
          '<div class="bar" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="' + pct +
            '" aria-label="' + esc(c.title) + ' progress toward ' + esc(c.goal) + '">' +
            '<span style="--pct:' + pct + '%"></span>' +
          '</div>' +
          '<a class="btn btn-dark cause-cta"' + linkAttrs(c) + '>' + esc(c.cta) + '</a>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  /* Titled bullet list — the stock-giving rationale and caveats. */
  function points(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (p, i) {
      return '<div class="point reveal"' + stagger(i) + '>' +
        '<h3>' + esc(p.title) + '</h3>' +
        '<p>' + esc(p.desc) + '</p>' +
      '</div>';
    }).join('');
  }

  /* FAQ. Native <details> so it opens without JavaScript and Ctrl-F still
     finds text inside a closed answer in browsers that support it. */
  function faq(targetId, arr) {
    var host = el(targetId);
    if (!host) return;
    host.innerHTML = arr.map(function (f) {
      return '<details class="faq-item">' +
        '<summary>' + esc(f.q) + '</summary>' +
        '<p>' + esc(f.a) + '</p>' +
      '</details>';
    }).join('');
  }

  window.D2URender = {
    sites: sites, founder: founder, funder: funder,
    cards: cards, people: people, tiles: tiles, events: events,
    tiers: tiers, stats: stats, numbered: numbered, theory: theory, marquee: marquee,
    gallery: gallery, moments: moments, logos: logos, charter: charter,
    need: need, metrics: metrics, categories: categories, giving: giving,
    stories: stories, pillars: pillars,
    ways: ways, causes: causes, points: points, faq: faq
  };
})();

/* ===== page-donate.js ===== */
/* Digi2U 2026 — page bootstrap for donate.
   Three live donation channels, none of which may be inlined into the page:
   the WordPress build asserts that a page ships zero inline <script> tags, and
   wpautop would rewrite one anyway. So the Zeffy iframes are written from here,
   and the DonateStock Easy Button loader — which used to be a raw <script> in
   the old Elementor HTML widget — is transcribed into this closure unchanged in
   behaviour. */
(function () {
  'use strict';

  var hero = document.getElementById('donateHero');
  if (hero) {
    hero.setAttribute('data-poster', D2U_CDN + 'd2u-cherry-xmas-3.webp');
    hero.setAttribute('data-label', 'Digi2U learners at a community build day');
  }

  D2URender.ways('waysGrid', D2U_DONATE_WAYS);
  D2URender.causes('causeGrid', D2U_CAUSES);
  D2URender.points('stockWhy', D2U_STOCK_WHY);
  D2URender.numbered('stockSteps', D2U_STOCK_STEPS);
  D2URender.points('stockKnow', D2U_STOCK_KNOW);
  D2URender.faq('donateFaq', D2U_DONATE_FAQ);

  /* ---------- Zeffy ----------
     Written from script rather than hard-coded in the markup so the campaign
     slug lives in exactly one place (data-donate.js). Both frames are
     third-party payment UI: they need payment-request permission, and the
     donation form needs enough height that the card step is not scrolled
     inside its own box on a phone. */
  function frame(hostId, src, title, allowPayment) {
    var host = document.getElementById(hostId);
    if (!host) return;
    var f = document.createElement('iframe');
    f.src = src;
    f.title = title;
    f.loading = 'lazy';
    f.setAttribute('allow', allowPayment ? 'payment' : '');
    f.setAttribute('allowpaymentrequest', 'true');
    host.appendChild(f);
  }
  frame('zeffyForm',   D2U_DONATE.zeffyEmbed,  'Donation form powered by Zeffy', true);
  frame('zeffyThermo', D2U_DONATE.zeffyThermo, 'Fundraising progress powered by Zeffy', false);

  /* ---------- Keep-in-touch capture ----------
     For the visitor who read the page and did not give today. Tagged as coming
     from the donate page so the sheet shows which addresses came from someone
     who got as far as considering a gift. */
  D2UForms.bind({
    form: 'donateSignup',
    note: 'ds-note',
    success: 'Thank you — we will write when there is something worth reporting.',
    collect: function () {
      return {
        name: '', phone: '', message: 'Donate page signup',
        email: document.getElementById('ds-email').value.trim(),
        subject: 'Newsletter signup',
        page: 'Donate'
      };
    }
  });

  /* ---------- DonateStock Easy Button ----------
     The loader is DonateStock's own snippet. It is kept verbatim so that a
     future version of their script behaves here exactly as it does on every
     other nonprofit page that uses it. */
  (function (w, d, s, o, f) {
    w[o] = w[o] || function () { (w[o].q = w[o].q || []).push(arguments); };
    var js = d.createElement(s), fjs = d.getElementsByTagName(s)[0];
    js.id = o; js.src = f; js.async = true;
    fjs.parentNode.insertBefore(js, fjs);
  }(window, document, 'script', 'dsEasyButton', 'https://donatestock.com/EasyButton.js'));

  var dsHost = document.getElementById('dsEasyButtonContainer');
  if (dsHost) {
    window.dsEasyButton('init', {
      element: dsHost,
      ein: D2U_DONATE.stockEin,
      preloadNonprofit: true,
      transferInstructionsLink: true,
      debug: false,
      style: { dark: false }
    });

    /* The plain link below the button is the fallback for a blocked or slow
       third-party script — it opens the same portal. Once the button has
       actually rendered, the link is redundant, so it steps aside rather than
       offering two controls that do the same thing. */
    var fallback = document.getElementById('dsFallback');
    if (fallback) {
      var settle = setInterval(function () {
        if (!dsHost.childElementCount) return;
        clearInterval(settle);
        fallback.hidden = true;
      }, 400);
      setTimeout(function () { clearInterval(settle); }, 12000);
    }
  }
}());

/* ===== site.js ===== */
/* ==========================================================================
   Digi2U 2026 — shared behaviour
   The lightbox mirrors Elementor Pro Popup: one trigger attribute per element,
   focus trapped while open, Esc + backdrop to close, deep-linkable via #hash.
   Elementor equivalent: #elementor-action:action=popup:open&settings=<id>
   ========================================================================== */
(function () {
  'use strict';

  /* ---------- Nav ---------- */
  var toggle = document.querySelector('.nav-toggle');
  var links = document.querySelector('.nav-links');
  if (toggle && links) {
    toggle.addEventListener('click', function () {
      var open = links.classList.toggle('open');
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
    links.addEventListener('click', function (e) {
      if (e.target.tagName === 'A') {
        links.classList.remove('open');
        toggle.setAttribute('aria-expanded', 'false');
      }
    });
  }

  /* ---------- Video backgrounds ----------
     The poster image is always painted first; the video only upgrades in when
     the connection and viewport can carry it. The hero clips are 0.9-2.9 MB
     (they were far heavier when this was first written, hence the old 900px
     cut-off, which withheld video from any desktop window under 900px wide —
     a laptop at 860px got a still image). The gate is now about phones and
     metered connections, which is what it was always meant to be about.
     Elementor equivalent: Section → Background → Video, with a Background
     Fallback image set and "Play on mobile" left off. */
  function videoIsWelcome() {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return false;
    /* A backgrounded or prerendered tab can report 0 here, which is "not
       measured yet" rather than "very small screen" — fall back to the
       documentElement before deciding the viewport is too narrow for video. */
    var w = window.innerWidth || document.documentElement.clientWidth || 0;
    if (w && w < 640) return false;
    var c = navigator.connection || navigator.mozConnection || navigator.webkitConnection;
    if (c) {
      if (c.saveData) return false;
      if (/^(slow-2g|2g|3g)$/.test(c.effectiveType || '')) return false;
    }
    return true;
  }

  /* Keyed on data-poster: a still image is mandatory, the video is optional.
     A host with only a poster is a photographic hero and stays that way. */
  document.querySelectorAll('[data-poster]').forEach(function (host) {
    var src = host.getAttribute('data-video');
    var poster = host.getAttribute('data-poster');
    var label = host.getAttribute('data-label') || '';
    if (!poster) return;

    var img = document.createElement('img');
    img.src = poster;
    img.alt = label;
    host.appendChild(img);

    if (!src || !videoIsWelcome()) return;

    var v = document.createElement('video');
    v.muted = true; v.loop = true; v.autoplay = true;
    v.playsInline = true; v.setAttribute('playsinline', '');
    v.setAttribute('aria-hidden', 'true');
    v.preload = 'auto';
    v.poster = poster;
    v.src = src;
    v.style.opacity = '0';
    v.style.transition = 'opacity .8s ease';

    v.addEventListener('canplay', function () {
      var p = v.play();
      if (p && p.catch) p.catch(function () { /* autoplay blocked — poster stands in */ });
      v.style.opacity = '1';
      img.style.display = 'none';
    }, { once: true });

    v.addEventListener('error', function () { v.remove(); });
    host.appendChild(v);
  });

  /* ---------- Autoplaying portrait promo ----------
     Same viewport and connection policy as the hero backgrounds: the poster
     paints immediately and the video only upgrades in where it is welcome, so
     a phone on cellular is not handed several megabytes unasked. Autoplay must
     be muted, so the clip carries its own sound toggle. */
  document.querySelectorAll('.vportrait[data-autoplay]').forEach(function (host) {
    var src = host.getAttribute('data-src');
    var poster = host.getAttribute('data-poster');
    var label = host.getAttribute('data-label') || '';
    if (!poster || !src) return;

    var img = document.createElement('img');
    img.src = poster;
    img.alt = label;
    host.insertBefore(img, host.firstChild);

    if (!videoIsWelcome()) return;      // poster stands in

    var v = document.createElement('video');
    v.muted = true; v.loop = true; v.autoplay = true;
    v.playsInline = true; v.setAttribute('playsinline', '');
    v.preload = 'auto';
    v.poster = poster;
    v.src = src;
    v.style.opacity = '0';
    v.style.transition = 'opacity .8s ease';

    v.addEventListener('canplay', function () {
      var p = v.play();
      if (p && p.catch) p.catch(function () { /* autoplay blocked — poster stands in */ });
      v.style.opacity = '1';
      img.style.display = 'none';
      btn.style.display = 'flex';
    }, { once: true });

    v.addEventListener('error', function () { v.remove(); btn.remove(); });
    host.insertBefore(v, host.firstChild);

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'vsound';
    btn.style.display = 'none';
    btn.setAttribute('aria-label', 'Turn sound on');
    btn.innerHTML =
      '<svg class="off" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3a4.5 4.5 0 0 0-2.5-4v8a4.5 4.5 0 0 0 2.5-4z" opacity=".45"/><path d="M19 5 5 19" stroke="currentColor" stroke-width="2"/></svg>' +
      '<svg class="on"  viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3a4.5 4.5 0 0 0-2.5-4v8a4.5 4.5 0 0 0 2.5-4zM14 1.2v2.06a8.5 8.5 0 0 1 0 17.48v2.06a10.5 10.5 0 0 0 0-21.6z"/></svg>';
    btn.addEventListener('click', function () {
      v.muted = !v.muted;
      btn.classList.toggle('is-on', !v.muted);
      btn.setAttribute('aria-label', v.muted ? 'Turn sound on' : 'Turn sound off');
      if (!v.muted) { var p = v.play(); if (p && p.catch) p.catch(function () {}); }
    });
    host.appendChild(btn);
  });

  /* ---------- Click-to-play portrait video ----------
     This clip is 13 MB. It loads only when someone asks for it — poster frame
     until then, so the section costs nothing to scroll past.
     Elementor equivalent: the Video widget with "Lightbox" on and a custom
     image overlay. */
  document.querySelectorAll('.vportrait[data-src]').forEach(function (host) {
    var poster = host.getAttribute('data-poster');
    var src = host.getAttribute('data-src');
    var btn = host.querySelector('.vportrait-play');

    if (poster) {
      var img = document.createElement('img');
      img.src = poster;
      img.alt = host.getAttribute('data-label') || '';
      host.insertBefore(img, host.firstChild);
    }
    if (!btn || !src) return;

    btn.addEventListener('click', function () {
      var v = document.createElement('video');
      v.src = src;
      v.controls = true;
      v.playsInline = true;
      v.setAttribute('playsinline', '');
      v.preload = 'auto';
      if (poster) v.poster = poster;
      host.insertBefore(v, host.firstChild);
      host.classList.add('playing');
      var p = v.play();
      if (p && p.catch) p.catch(function () { /* user can hit the native control */ });
    }, { once: true });
  });

  /* ---------- Chapter numbering ----------
     Renumber in DOM order rather than trusting the hard-coded markup: a section
     can remove itself (Stories does, when there is no verified testimony), and
     a gap in the sequence reads as a mistake. Runs after the renderers. */
  var chapterNums = document.querySelectorAll('.chapter .num');
  if (chapterNums.length) {
    chapterNums.forEach(function (el, i) {
      el.textContent = String(i + 1).padStart(2, '0');
    });
  }

  /* ---------- Reveal on scroll ---------- */
  var revealables = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window && revealables.length) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); }
      });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.05 });
    revealables.forEach(function (el) { io.observe(el); });
  } else {
    revealables.forEach(function (el) { el.classList.add('in'); });
  }

  /* ---------- Lightbox ---------- */
  var lb = document.getElementById('lb');
  if (!lb) return;
  var panel = lb.querySelector('.lb-panel');
  var lastFocus = null;

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function metaBlock(meta) {
    if (!meta || !meta.length) return '';
    return '<div class="lb-meta">' + meta.map(function (m) {
      return '<div><strong>' + esc(m[0]) + '</strong><span>' + esc(m[1]) + '</span></div>';
    }).join('') + '</div>';
  }

  function bulletList(bullets) {
    if (!bullets || !bullets.length) return '';
    return '<ul class="lb-list">' + bullets.map(function (b) {
      return Array.isArray(b)
        ? '<li><b>' + esc(b[0]) + '</b><span>' + esc(b[1]) + '</span></li>'
        : '<li><span>' + esc(b) + '</span></li>';
    }).join('') + '</ul>';
  }

  var ctaApply =
    '<div class="lb-foot">' +
      '<a class="btn btn-primary" href="get-involved.html#contact">Apply / Inquire</a>' +
      '<a class="btn btn-ghost" href="get-involved.html#donate">Support This Program</a>' +
    '</div>';

  /* --- Builders, one per content type --- */
  var build = {
    program: function (d) {
      return (d.img ? '<div class="lb-hero" style="background-image:url(' + esc(d.img) + ')"></div>' : '') +
        '<div class="lb-body">' +
          (d.tag ? '<span class="lb-tag">' + esc(d.tag) + '</span>' : '') +
          (d.kicker ? '<div class="lb-kicker">' + esc(d.kicker) + '</div>' : '') +
          '<h2>' + esc(d.title) + '</h2>' +
          '<p>' + esc(d.desc || d.short) + '</p>' +
          metaBlock(d.meta) +
          (d.bullets && d.bullets.length ? '<div class="lb-sub">What you\u2019ll learn</div>' + bulletList(d.bullets) : '') +
          ctaApply +
        '</div>';
    },

    person: function (d) {
      var exp = (d.experience || []).map(function (e) {
        return '<div class="lb-exp">' +
          '<h4>' + esc(e.role) + (e.company ? ' · ' + esc(e.company) : '') + '</h4>' +
          (e.dates ? '<div class="when">' + esc(e.dates) + '</div>' : '') +
          (e.desc ? '<p>' + esc(e.desc) + '</p>' : '') +
        '</div>';
      }).join('');
      var skills = (d.expertise || []).map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('');
      var links = (d.links || []).map(function (l) {
        return '<a class="btn btn-ghost" href="' + esc(l.href) + '" target="_blank" rel="noopener">' + esc(l.label) + '</a>';
      }).join('');
      return '<div class="lb-body">' +
        '<div class="lb-person">' +
          (d.img ? '<img class="lb-person-img" src="' + esc(d.img) + '" alt="' + esc(d.name) + '" loading="lazy">' : '') +
          '<div>' +
            (d.role ? '<span class="lb-tag">' + esc(d.role) + '</span>' : '') +
            '<h2>' + esc(d.name) + '</h2>' +
            (d.tagline ? '<div class="lb-kicker" style="margin-top:8px">' + esc(d.tagline) + '</div>' : '') +
          '</div>' +
        '</div>' +
        (d.bio ? '<p style="margin-top:22px">' + esc(d.bio) + '</p>' : '') +
        (exp ? '<div class="lb-sub">Experience</div>' + exp : '') +
        (skills ? '<div class="lb-sub">Expertise</div><ul class="lb-chips">' + skills + '</ul>' : '') +
        (links ? '<div class="lb-foot">' + links + '</div>' : '') +
      '</div>';
    },

    partner: function (d) {
      var secs = (d.sections || []).map(function (s) {
        return '<div class="lb-sub">' + esc(s.title) + '</div>' +
          (s.sub ? '<div class="lb-kicker">' + esc(s.sub) + '</div>' : '') +
          (s.body ? '<p style="margin-bottom:14px">' + esc(s.body) + '</p>' : '') +
          bulletList(s.bullets);
      }).join('');
      return '<div class="lb-body">' +
        '<span class="lb-tag">' + esc(d.tag) + '</span>' +
        '<h2>' + esc(d.name) + '</h2>' +
        '<p>' + esc(d.desc) + '</p>' +
        (d.collab ? '<div class="note"><strong>Program collaboration</strong>' + esc(d.collab) + '</div>' : '') +
        secs +
        '<div class="lb-foot"><a class="btn btn-primary" href="get-involved.html#contact">Become A Partner</a></div>' +
      '</div>';
    },

    doc: function (d) {
      return '<div class="lb-body">' +
        '<span class="lb-tag">' + esc(d.status) + '</span>' +
        '<div class="lb-kicker">' + esc(d.credit) + '</div>' +
        '<h2>' + esc(d.title) + '</h2>' +
        '<p>' + esc(d.desc) + '</p>' +
        '<div class="lb-sub">About the film</div>' +
        '<p>' + esc(d.body) + '</p>' +
        '<div class="lb-foot"><a class="btn btn-primary" href="get-involved.html#donate">Support Our Films</a></div>' +
      '</div>';
    },

    role: function (d) {
      return '<div class="lb-body">' +
        '<span class="lb-tag">Now Hiring</span>' +
        '<h2>' + esc(d.title) + '</h2>' +
        '<p>' + esc(d.desc) + '</p>' +
        metaBlock(d.meta) +
        '<div class="lb-sub">What you\u2019ll actually do</div>' +
        bulletList(window.D2U_ROLE_DUTIES || []) +
        '<div class="lb-foot"><a class="btn btn-primary" href="#apply" data-lb-close>Apply For This Role</a></div>' +
      '</div>';
    },

    tier: function (d) {
      return '<div class="lb-body">' +
        '<span class="lb-tag">' + esc(d.tag) + '</span>' +
        '<h2>' + esc(d.name) + '</h2>' +
        '<div class="tier-amt" style="margin:14px 0 22px">' + esc(d.amount) + '</div>' +
        '<div class="lb-sub" style="margin-top:0;padding-top:0;border:0">What is included</div>' +
        bulletList(d.benefits) +
        '<div class="lb-foot"><a class="btn btn-primary" href="#contact" data-lb-close>Talk Sponsorship</a></div>' +
      '</div>';
    },

    event: function (d) {
      return '<div class="lb-body">' +
        '<span class="lb-tag">' + esc(d.tag) + '</span>' +
        '<h2>' + esc(d.title) + '</h2>' +
        '<p>' + esc(d.desc) + '</p>' +
        metaBlock(d.meta) +
        '<div class="lb-foot"><a class="btn btn-primary" href="get-involved.html#contact">Reserve A Seat</a></div>' +
      '</div>';
    },

    photo: function (d) {
      return '<img class="lb-photo" src="' + esc(d.src) + '" alt="' + esc(d.cap) + '">' +
        '<div class="lb-photo-cap"><b>' + esc(d.cat) + '</b><span>' + esc(d.cap) + '</span></div>';
    },

    /* Static HTML pulled from a <template> already in the page. */
    node: function (_d, id) {
      var tpl = document.getElementById(id);
      return '<div class="lb-body">' + (tpl ? tpl.innerHTML : '') + '</div>';
    }
  };

  /* Registry: populated per page via D2U.register() */
  var sources = {};
  window.D2U = window.D2U || {};
  window.D2U.register = function (type, dict) { sources[type] = dict; };

  function open(type, key, trigger) {
    var fn = build[type];
    if (!fn) return;
    var data = (sources[type] || {})[key];
    if (type !== 'node' && !data) return;

    lastFocus = trigger || document.activeElement;
    panel.className = 'lb-panel' + (type === 'photo' ? ' photo' : '');
    panel.innerHTML =
      '<button class="lb-close" type="button" aria-label="Close">' +
        '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">' +
          '<path d="M5 5 L19 19 M19 5 L5 19" />' +
        '</svg>' +
      '</button>' + fn(data, key);
    lb.classList.add('open');
    lb.setAttribute('aria-hidden', 'false');
    document.body.classList.add('lb-locked');
    lb.scrollTop = 0;
    var closeBtn = panel.querySelector('.lb-close');
    if (closeBtn) closeBtn.focus();
  }

  function close() {
    lb.classList.remove('open');
    lb.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('lb-locked');
    panel.innerHTML = '';
    if (lastFocus && lastFocus.focus) lastFocus.focus();
    if (location.hash.indexOf('#lb-') === 0) {
      history.replaceState(null, '', location.pathname + location.search);
    }
  }

  window.D2U.openLightbox = open;

  /* Delegated trigger: any element with data-lb="type:key" */
  document.addEventListener('click', function (e) {
    var t = e.target.closest('[data-lb]');
    if (t) {
      e.preventDefault();
      var parts = t.getAttribute('data-lb').split(':');
      open(parts[0], parts.slice(1).join(':'), t);
      return;
    }
    if (e.target.closest('[data-lb-close]')) { close(); return; }
    if (e.target.closest('.lb-close')) { close(); return; }
    if (e.target === lb) close();
  });

  document.addEventListener('keydown', function (e) {
    if (!lb.classList.contains('open')) return;
    if (e.key === 'Escape') { close(); return; }
    if (e.key !== 'Tab') return;
    var f = panel.querySelectorAll('a[href], button:not([disabled]), input, select, textarea');
    if (!f.length) return;
    var first = f[0], last = f[f.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  });

  /* Deep link: #lb-program-drone opens that popup on load. */
  function fromHash() {
    var h = location.hash;
    if (h.indexOf('#lb-') !== 0) return;
    var rest = h.slice(4);
    var i = rest.indexOf('-');
    if (i < 0) return;
    open(rest.slice(0, i), rest.slice(i + 1));
  }
  window.addEventListener('load', fromHash);
})();

/* ===========================================================================
   Donate lightbox
   Donating used to send people to Zeffy on another domain, which loses the
   context they were reading in and, on mobile, usually loses them entirely.
   The form now opens over the page.

   The iframe src is only set when the overlay opens, so the Zeffy embed costs
   nothing on pages nobody donates from. Scroll is locked while open, Esc and
   the backdrop close it, and focus returns to the button that opened it.
   Any link pointing at #donate or at zeffy.com is intercepted, so the nav
   button, the hero CTAs and the giving section all behave the same. Two
   exceptions: a link that asked for target="_blank", and any page that already
   embeds the form itself (the donate page).
   ========================================================================= */
(function () {
  var ZEFFY = 'https://www.zeffy.com/embed/donation-form/donate-to-change-lives-3894';
  var ov, frame, opener;

  function build() {
    if (ov) return ov;
    ov = document.createElement('div');
    ov.className = 'd2u-donate-ov';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.setAttribute('aria-label', 'Donate to Digi2U');
    ov.innerHTML =
      '<div class="d2u-donate-box">' +
        '<div class="d2u-donate-head">' +
          '<strong>Donate to Digi2U</strong>' +
          '<button type="button" class="d2u-donate-close" aria-label="Close">&times;</button>' +
        '</div>' +
        '<iframe title="Donation form powered by Zeffy" allowpaymentrequest allowtransparency="true" loading="lazy"></iframe>' +
        '<div class="d2u-donate-foot">Digi2U is a 501(c)(3) — EIN 88-3213984. All gifts are tax-deductible. ' +
        'Trouble loading? <a href="https://www.zeffy.com/donation-form/donate-to-change-lives-3894" target="_blank" rel="noopener">Open the form in a new tab</a>.</div>' +
      '</div>';
    document.body.appendChild(ov);
    frame = ov.querySelector('iframe');
    ov.querySelector('.d2u-donate-close').addEventListener('click', close);
    ov.addEventListener('mousedown', function (e) { if (e.target === ov) close(); });
    return ov;
  }

  function open(from) {
    build();
    opener = from || null;
    if (!frame.getAttribute('src')) frame.setAttribute('src', ZEFFY);
    ov.classList.add('is-open');
    document.documentElement.style.overflow = 'hidden';
    document.body.style.overflow = 'hidden';
    var btn = ov.querySelector('.d2u-donate-close');
    if (btn) btn.focus();
  }

  function close() {
    if (!ov) return;
    ov.classList.remove('is-open');
    document.documentElement.style.overflow = '';
    document.body.style.overflow = '';
    if (opener && opener.focus) opener.focus();
  }

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && ov && ov.classList.contains('is-open')) close();
  });

  document.addEventListener('click', function (e) {
    var a = e.target.closest && e.target.closest('a[href]');
    if (!a) return;
    /* An author who wrote target="_blank" asked for a new tab and meant it —
       overriding that turns a stated promise into a lie. */
    if (a.target === '_blank') return;
    /* And the donate page embeds this very form in the document, so opening a
       second copy of it over the first would be pure noise. */
    if (document.getElementById('zeffyForm')) return;
    var href = a.getAttribute('href') || '';
    if (href.indexOf('#donate') === -1 && href.indexOf('zeffy.com') === -1) return;
    e.preventDefault();
    open(a);
  });
})();

/* ===========================================================================
   Footer signup
   The one form that appears on every page, so it is bound here rather than in
   each page bootstrap. Google needs a Subject on every row; "Newsletter
   signup" is what makes these separable from enquiries in the sheet, and Page
   records which page earned the address.
   ========================================================================= */
(function () {
  if (!window.D2UForms) return;
  D2UForms.bind({
    form: 'footSignup',
    note: 'fs-note',
    success: 'You are on the list. Watch for the next one.',
    collect: function () {
      var page = (document.title.split('—')[0] || '').trim() || location.pathname;
      return {
        name: '', phone: '', message: 'Footer signup',
        email: document.getElementById('fs-email').value.trim(),
        subject: 'Newsletter signup',
        page: page + ' (footer)'
      };
    }
  });
}());

/* Page bootstraps (assets/page-*.js) render their content before this file runs,
   then leave any lightbox registration here — D2U.register only exists once the
   IIFE above has executed. */
if (typeof window.__D2U_INIT === 'function') {
  window.__D2U_INIT();
  delete window.__D2U_INIT;
}

